sys_script_include.script:
var HoCOHSMQuery = Class.create();
HoCOHSMQuery.prototype = {
    initialize: function() {
    },

	getLocationName: function(sys_id){
		var gr = new GlideRecord('cmn_location');
		gr.get('sys_id',sys_id);
		gr.query();
		while (gr.next()) {
			return gr.getDisplayValue();    
		}
		return "(ERROR: Location not found)";
	},
    type: 'HoCOHSMQuery'
};
